import javax.swing.*;
import java.awt.*;

// 校园一卡通云打卡桌面客户端 / 模拟打卡调试窗口
public class CloudPunchClient {
    public static void main(String[] args) {
        JFrame frame = new JFrame("校园一卡通 · 云打卡终端 (NTZX Cloud Punch)");
        Container container = frame.getContentPane();

        JButton btnStart = new JButton("开始打卡");
        JButton btnRead = new JButton("读取打卡记录");

        container.setLayout(new FlowLayout());
        container.add(btnStart);
        container.add(btnRead);

        frame.setLocation(100, 100);
        frame.setSize(600, 500);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);
        System.out.println("云打卡调试前端已启动，等待 NFC 读卡器触发事件...");
    }
}
